def inorderTraversal(root):
    if root is None:
        return []

    result = []
    def traverse(node):
        if node is not None:
            traverse(node.left)
            result.append(node.val)
            traverse(node.right)

    traverse(root)
    return result

class BinaryTree:
    def __init__(self):
        self.head = None

    def add(self, val):
        if self.head is None:
            self.head = TreeNode(val)
        else:
            self._add(self.head, val)

    def _add(self, node, val):
        if val < node.val:
            if node.left is None:
                node.left = TreeNode(val)
            else:
                self._add(node.left, val)
        else:
            if node.right is None:
                node.right = TreeNode(val)
            else:
                self._add(node.right, val)

    def inorder(self):
        return inorderTraversal(self.head)

