def shortestPath(graph, start, end):
    n = len(graph)
    queue = [(0, start, [])]
    visited = set()
    while queue:
        d, node, path = heapq.heappop(queue)
        if node == end:
            return path + [node]
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                heapq.heappush(queue, (d + 1, neighbor, path + [node]))
    return []

