def minimumSpanningTree(graph):
    n = len(graph)
    parent = list(range(n))
    rank = [0] * n
    edges = []
    for u in range(n):
        for v in range(u + 1, n):
            edges.append((graph[u][v], u, v))
    heapq.heapify(edges)
    mst = []
    while edges:
        weight, u, v = heapq.heappop(edges)
        if find(parent, u) != find(parent, v):
            mst.append((u, v, weight))
            union(parent, rank, u, v)
    return mst

def find(parent, node):
    if parent[node] != node:
        parent[node] = find(parent, parent[node])
    return parent[node]

def union(parent, rank, u, v):
    rootU = find(parent, u)
    rootV = find(parent, v)
    if rootU != rootV:
        if rank[rootU] > rank[rootV]:
            parent[rootV] = rootU
        else:
            parent[rootU] = rootV
            if rank[rootU] == rank[rootV]:
                rank[rootV] += 1

