def numWays(sticks, target):
    ways = [[0]*(target+1) for _ in range(len(sticks)+1)]
    for i in range(1, len(sticks)+1):
        for j in range(1, target+1):
            if sticks[i-1] <= j:
                ways[i][j] = ways[i-1][j] + ways[i-1][j-sticks[i-1]]
            else:
                ways[i][j] = ways[i-1][j]
    return [ways[i][target] for i in range(1, len(sticks)+1)]
