def largestDivisibleSubset(nums):
    if not nums:
        return []
    nums.sort()
    dp = [[num] for num in nums]
    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] % nums[j] == 0 and len(dp[j]) + 1 > len(dp[i]):
                dp[i] = dp[j] + [nums[i]]
    return max(dp, key=len)
